import pandas as pd

def clean(df):
    df = df.copy()
    # Fix misspelled category labels
    df['Category'] = df['Category'].replace({
        'Office Suplies': 'Office Supplies',
        'Accesories': 'Accessories'
    })
    # Remove exact duplicate rows (e.g., Order_ID 2004 appears twice)
    df = df.drop_duplicates()
    return df

def answer(df):
    df = clean(df)
    grouped = df.groupby('Category')['Revenue'].sum()
    return grouped.to_dict()
